function escapeJSONString(str) {
  return str
    .replace(/\\/g, '\\\\')   // escape dấu \
    .replace(/"/g, '\\"')     // escape dấu "
    .replace(/\n/g, '\\n')    // escape newline
    .replace(/\r/g, '\\r')    // escape carriage return
    .replace(/\t/g, '\\t');   // escape tab
}

