function escapeJSONString(str) {
  return str
    .replace(/\\/g, '\\\\')   // escape dấu \
    .replace(/"/g, '\\"')     // escape dấu "
    .replace(/\n/g, '\\n')    // escape newline
    .replace(/\r/g, '\\r')    // escape carriage return
    .replace(/\t/g, '\\t');   // escape tab
}

// Lấy dữ liệu từ input (giả sử là $json.output)
const originalMessage = $input.first().json.output.output || '';

// Escape và định dạng JSON
const escapedMessage = escapeJSONString(originalMessage);

// Trả về kết quả theo định dạng n8n
