// Danh sách các từ viết liền thông dụng cần thay thế
const commonTerms = {
  'productid': 'product id',
  'sporttype': 'sport type',
  'bettype': 'bet type',
  'sportbook': 'sportsbook',
  'cs': 'casino',
  'sp': 'sportsbook',
  'win loss': 'winloss'
  // Thêm các từ viết liền khác nếu cần
};
const userInput = $input.first().json.chatInput;

function normalizeText(text) {
  // Chuyển tất cả về chữ thường
  text = text.toLowerCase();

  // Thay thế các từ viết liền thông dụng
  for (let term in commonTerms) {
    const regex = new RegExp(term, 'g');
    text = text.replace(regex, commonTerms[term]);
  }
  // Loại bỏ các ký tự đặc biệt như dấu gạch dưới và dấu cách
  text = text.replace(/[_\s]+/g, ' ');  // Thay dấu gạch dưới và dấu cách bằng dấu cách duy nhất

  // Trả về văn bản đã chuẩn hóa
  return text;
}

const formattedInput = {
  chatInput: normalizeText(userInput)
};
return formattedInput;
